mapper.select:
SELECT COUNT(*)
FROM orders

    order_time >= #{q.startDate} AND order_time < DATE_ADD(#{q.endDate}, INTERVAL 1 DAY)
    AND category = #{q.category}
    AND pay_type = #{q.payType}
    AND user_type = #{q.userType}
    AND promo_flag = #{q.promoFlag}

        AND (order_id LIKE CONCAT('%', #{q.keyword}, '%') OR product_name LIKE CONCAT('%', #{q.keyword}, '%'))

SELECT order_id, product_name, category, price, quantity, total_amount, order_time,
       user_id, user_type, pay_type, promo_flag, region
FROM orders

    order_time >= #{q.startDate} AND order_time < DATE_ADD(#{q.endDate}, INTERVAL 1 DAY)
    AND category = #{q.category}
    AND pay_type = #{q.payType}
    AND user_type = #{q.userType}
    AND promo_flag = #{q.promoFlag}

        AND (order_id LIKE CONCAT('%', #{q.keyword}, '%') OR product_name LIKE CONCAT('%', #{q.keyword}, '%'))


ORDER BY ${sortColumn} ${sortDirection}
LIMIT #{offset}, #{size}

SELECT product_name AS productName, ROUND(SUM(total_amount), 2) AS sales, SUM(quantity) AS quantity FROM orders
order_time >= #{q.startDate} AND order_time < DATE_ADD(#{q.endDate}, INTERVAL 1 DAY) AND category = #{q.category}
GROUP BY product_name ORDER BY ${orderBy} DESC LIMIT #{limit}

SELECT ${granularity.expr} AS period, ROUND(SUM(total_amount), 2) AS sales, COUNT(*) AS orders FROM orders
order_time >= #{startDate} AND order_time < DATE_ADD(#{endDate}, INTERVAL 1 DAY) AND category = #{category}
GROUP BY period ORDER BY period ASC

SELECT t.range_label AS `range`, COUNT(*) AS orderCount, ROUND(SUM(t.total_amount), 2) AS sales FROM ( SELECT total_amount, CASE WHEN total_amount < 100 THEN '0-100' WHEN total_amount < 300 THEN '100-300' WHEN total_amount < 500 THEN '300-500' WHEN total_amount < 1000 THEN '500-1000' WHEN total_amount < 5000 THEN '1000-5000' ELSE '5000以上' END AS range_label FROM orders
order_time >= #{startDate} AND order_time < DATE_ADD(#{endDate}, INTERVAL 1 DAY) AND category = #{category}
) t GROUP BY t.range_label ORDER BY MIN(t.total_amount)

SELECT HOUR(order_time) AS hour, COUNT(*) AS orderCount, ROUND(SUM(total_amount), 2) AS sales FROM orders
order_time >= #{startDate} AND order_time < DATE_ADD(#{endDate}, INTERVAL 1 DAY) AND category = #{category}
GROUP BY HOUR(order_time) ORDER BY hour ASC

SELECT user_type AS userType, COUNT(DISTINCT user_id) AS userCount, ROUND(SUM(total_amount), 2) AS sales, COUNT(*) AS orderCount FROM orders
order_time >= #{startDate} AND order_time < DATE_ADD(#{endDate}, INTERVAL 1 DAY) AND category = #{category}
GROUP BY user_type

SELECT pay_type AS payType, COUNT(*) AS orderCount, ROUND(COUNT(*) / SUM(COUNT(*)) OVER (), 4) AS rate FROM orders
order_time >= #{startDate} AND order_time < DATE_ADD(#{endDate}, INTERVAL 1 DAY) AND category = #{category}
GROUP BY pay_type ORDER BY orderCount DESC

SELECT COUNT(*) FROM ( SELECT user_id FROM orders
order_time >= #{startDate} AND order_time < DATE_ADD(#{endDate}, INTERVAL 1 DAY) AND category = #{category}
GROUP BY user_id HAVING COUNT(*) > 1 ) t

SELECT user_id AS userId, COUNT(*) AS frequency, ROUND(SUM(total_amount), 2) AS monetary, DATEDIFF(#{windowEnd}, MAX(order_time)) AS recencyDays FROM orders
order_time >= #{startDate} AND order_time < DATE_ADD(#{endDate}, INTERVAL 1 DAY) AND category = #{category}
GROUP BY user_id

SELECT id, order_id, product_name, category, price, quantity, total_amount,
       order_time, user_id, user_type, pay_type, promo_flag, region
FROM orders

    order_time >= #{q.startDate} AND order_time < DATE_ADD(#{q.endDate}, INTERVAL 1 DAY)
    AND id > #{lastId}
    AND category = #{q.category}

        AND (order_id LIKE CONCAT('%', #{q.keyword}, '%') OR product_name LIKE CONCAT('%', #{q.keyword}, '%'))

    AND pay_type = #{q.payType}
    AND user_type = #{q.userType}

ORDER BY id ASC
LIMIT #{size}
